"""Controlled execution fixture. This is not the REA engine or its API."""
import argparse
import hashlib
import json
from pathlib import Path
import re
import uuid

ROOT = Path(__file__).resolve().parent
STATE = ROOT / 'evidence' / 'engine-session.json'
SCHEMA = {
    'provider': 'controlled-cli-fixture-v1',
    'commands': {
        'schema': 'print this contract',
        'acquire': {'required': ['--target', '--sha256', '--function'], 'output': 'complete dossier and retained reference'},
        'compare': {'required': ['--left', '--right'], 'arguments': 'JSON objects: {"kind":"retained-evidence","evidence_id":"<issued id>"}'},
    },
    'session': 'retained references work only in the current fixture session',
    'scope': 'only a literal integer return in the selected function; targets are read as data, never executed',
    'errors': ['identity_mismatch', 'invalid_reference', 'unknown_evidence', 'unsupported_selection'],
}

def fail(reason):
    print(json.dumps({'ok': False, 'provider': SCHEMA['provider'], 'error': reason}))
    raise SystemExit(2)

def main():
    p = argparse.ArgumentParser(description=__doc__)
    sub = p.add_subparsers(dest='command', required=True)
    sub.add_parser('schema')
    a = sub.add_parser('acquire')
    for key in ['target', 'sha256', 'function']:
        a.add_argument('--' + key, required=True)
    c = sub.add_parser('compare')
    c.add_argument('--left', required=True)
    c.add_argument('--right', required=True)
    args = p.parse_args()
    if args.command == 'schema':
        print(json.dumps(SCHEMA, indent=2)); return
    state = json.loads(STATE.read_text()) if STATE.exists() else {'session_id': str(uuid.uuid4()), 'records': {}}
    if args.command == 'acquire':
        target = (ROOT / args.target).resolve()
        if not target.is_relative_to(ROOT / 'targets') or not target.is_file():
            fail('unsupported_selection')
        data = target.read_bytes()
        digest = hashlib.sha256(data).hexdigest()
        if digest != args.sha256:
            fail('identity_mismatch')
        matches = re.findall(r'function\s+' + re.escape(args.function) + r'\s*\(\s*\)\s*\{\s*return\s+(\d+)\s*;\s*\}', data.decode())
        if len(matches) != 1:
            fail('unsupported_selection')
        eid = 'fixture-' + str(uuid.uuid4())
        dossier = {'evidence_id': eid, 'provider': SCHEMA['provider'], 'session_id': state['session_id'], 'kind': 'complete-dossier', 'subject': {'path': args.target, 'sha256': digest}, 'normalized_result': {'function': args.function, 'literal_integer_return': int(matches[0])}, 'coverage': 'selected literal function only', 'limitations': ['static source observation', 'not runtime execution', 'not a real REA provider']}
        state['records'][eid] = dossier
        STATE.parent.mkdir(exist_ok=True)
        STATE.write_text(json.dumps(state, indent=2) + '\n')
        print(json.dumps({'ok': True, 'dossier': dossier, 'reference': {'kind': 'retained-evidence', 'evidence_id': eid}}, indent=2)); return
    records = []
    for value in [args.left, args.right]:
        try: ref = json.loads(value)
        except ValueError: fail('invalid_reference')
        if not isinstance(ref, dict) or set(ref) != {'kind', 'evidence_id'} or ref['kind'] != 'retained-evidence':
            fail('invalid_reference')
        eid = ref['evidence_id']
        if not isinstance(eid, str) or eid not in state['records']:
            fail('unknown_evidence')
        record = state['records'][eid]
        if record['session_id'] != state['session_id']: fail('unknown_evidence')
        records.append(record)
    print(json.dumps({'ok': True, 'provider': SCHEMA['provider'], 'session_id': state['session_id'], 'inputs': records, 'normalized_result': {'left_literal': records[0]['normalized_result']['literal_integer_return'], 'right_literal': records[1]['normalized_result']['literal_integer_return']}, 'coverage': 'selected literal functions; runtime and other code unknown'}, indent=2))

if __name__ == '__main__':
    main()
